export const escapeStaff=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={pin:'m16 3 5 5-4 1-4 4v4l-2 2-6-6 2-2h4l4-4 1-4ZM3 21l5-5',messages:'M21 14a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4v7Z',publications:'M4 4h16v16H4ZM8 8h8M8 12h8M8 16h5',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87',chat:'M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7A8.38 8.38 0 0 1 4 11.5a8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9H13a8.48 8.48 0 0 1 8 8v.5Z',support:'M21 15a4 4 0 0 1-4 4H7l-4 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4ZM7 8h10M7 12h7',reciter:'M3 14v-3a9 9 0 0 1 18 0v3M5 12h2v8H5a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2ZM19 12h-2v8h2a2 2 0 0 0 2-2v-4a2 2 0 0 0-2-2Z',wallpaper:'M3 3h18v18H3ZM3 17l6-6 4 4 3-3 5 5',review:'M9 3H5v18h14V3h-4M9 2h6v4H9ZM8 13l3 3 5-6',audit:'M8 3H5v18h14V3h-4M9 2h6v4H9ZM8 10h8M8 14h8M8 18h4',close:'M6 6l12 12M18 6 6 18',send:'m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13',file:'m21 11-8.5 8.5a6 6 0 0 1-8.5-8.5L13 2a4 4 0 0 1 5.7 5.7L10 16.3a2 2 0 0 1-2.8-2.8l8-8',smile:'M8 14s1.5 3 4 3 4-3 4-3M8 8v1M16 8v1',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-4 10 3 3 5-6',plus:'M12 5v14M5 12h14',back:'m15 18-6-6 6-6',logout:'M9 4H3v16h6M10 12h11m-4-4 4 4-4 4'};
export function staffIcon(name){return '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">'+(name==='team'?'<circle cx="9" cy="7" r="4"/>':name==='smile'?'<circle cx="12" cy="12" r="10"/>':'')+'<path d="'+(paths[name]||paths.team)+'"/></svg>';}
export const roleLabel=role=>({owner:'Владелец',admin:'Администратор',moderator:'Модератор'}[role]||'Сотрудник');
export function staffTabs(actor){return [...(actor.owner?[['team','Сотрудники']]:[]),['messages','Сообщения'],...(actor.permissions.some(x=>['reciters','wallpapers'].includes(x))?[['publications','Материалы']]:[]),...(actor.owner?[['review','На проверку'],['audit','История']]:[])];}
export function staffShell(actor,tab,{demo=false,embedded=false}={}){return '<section class="staff-cabinet"><header class="staff-heading"><div><span class="staff-eyebrow">SALAH · '+escapeStaff(roleLabel(actor.role))+'</span>'+(embedded?'<h2>Команда SALAH</h2>':'<h1>Кабинет команды</h1>')+'</div><a class="staff-icon-button" href="'+(embedded?'#admin?view=overview':'#account')+'" aria-label="'+(embedded?'Вернуться к обзору':'Вернуться в аккаунт')+'">'+staffIcon('close')+'</a></header>'+(demo?'<div class="staff-demo">Локальный макет · тестовые аккаунты · рабочая база не подключена</div>':'')+'<nav class="staff-tabs" data-count="'+staffTabs(actor).length+'" aria-label="Разделы кабинета">'+staffTabs(actor).map(([id,label])=>'<button type="button" data-staff-tab="'+id+'" aria-current="'+(id===tab?'page':'false')+'">'+staffIcon(id)+'<span>'+label+'</span>'+(id==='messages'?'<span class="staff-message-count" data-staff-message-count hidden></span>':'')+'</button>').join('')+'</nav><p class="staff-status" role="status" aria-live="polite"></p><div class="staff-content"></div></section>';}
export function memberRow(row,{embedded=false}={}){return '<div class="staff-member'+(embedded?' is-owner-member':'')+'"><span class="staff-avatar" data-member-avatar="'+escapeStaff(row.id)+'" aria-hidden="true">'+escapeStaff([...row.nickname||'С'].slice(0,2).join('').toUpperCase())+'</span><div class="staff-member-name"><strong>'+escapeStaff(row.nickname)+'</strong><small>'+escapeStaff(row.active?roleLabel(row.role):'Доступ закрыт')+'</small></div>'+(embedded?'<span class="staff-role-caption">Роль сотрудника</span>':'')+'<select aria-label="Роль для '+escapeStaff(row.nickname)+'" data-member-role="'+escapeStaff(row.id)+'"><option value="moderator"'+(row.role==='moderator'?' selected':'')+'>Модератор</option><option value="admin"'+(row.role==='admin'?' selected':'')+'>Администратор</option></select><button class="staff-icon-button" data-member-save="'+escapeStaff(row.id)+'" aria-label="'+(row.active?'Сохранить роль':'Вернуть доступ')+'">'+staffIcon('review')+(embedded?'<span>'+(row.active?'Сохранить роль':'Назначить')+'</span>':'')+'</button>'+(row.active?'<button class="staff-icon-button" data-member-revoke="'+escapeStaff(row.id)+'" aria-label="Закрыть доступ '+escapeStaff(row.nickname)+'">'+staffIcon('logout')+(embedded?'<span>Отозвать доступ</span>':'')+'</button>':'')+'</div>';}
export const draftStatus=x=>({draft:'Черновик',submitted:'На проверке',changes_requested:'Нужны исправления',rejected:'Отклонено',published:'Опубликовано'}[x]||x);
export function draftRow(row){return '<button class="staff-list-row" type="button" data-draft="'+escapeStaff(row.id)+'"><span>'+staffIcon(row.kind)+'</span><div><strong>'+escapeStaff(row.payload?.name||row.entity_id)+'</strong><small>'+escapeStaff(row.author_name||'')+'</small></div><span class="staff-chip is-'+escapeStaff(row.status)+'">'+escapeStaff(draftStatus(row.status))+'</span></button>';}
export function chatBubble(message,files,uid){const mine=message.author_id===uid;return '<article class="staff-message'+(mine?' is-mine':'')+'" data-message="'+escapeStaff(message.id)+'"><div class="staff-bubble"><strong>'+escapeStaff(message.author_name)+'</strong><p>'+escapeStaff(message.redacted?'Сообщение удалено':message.body)+'</p>'+files.filter(f=>f.message_id===message.id).map(f=>'<a class="staff-file" href="'+escapeStaff(f.url)+'" target="_blank" rel="noopener noreferrer" download="'+escapeStaff(f.filename)+'" data-file="'+escapeStaff(f.id)+'">'+staffIcon('file')+'<span>'+escapeStaff(f.filename)+'<small>'+Math.max(1,Math.round(f.bytes/1024))+' КБ</small></span></a>').join('')+'<time>'+escapeStaff(new Date(message.created_at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}))+(mine&&message.seen?' · Прочитано':'')+'</time></div></article>';}
